insert into public.quiz_questions (question_number, era_id, event_id, question_text, explanation, difficulty, is_published)
values
    (1, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'cach-mang-thang-8'), 'Cách mạng Tháng Tám diễn ra vào năm nào?', 'Cách mạng Tháng Tám năm 1945 lật đổ chế độ phong kiến và ách đô hộ thực dân, mở ra kỷ nguyên độc lập.', 'easy', true),
    (2, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'doc-lap-1945'), 'Ai là người đọc Tuyên ngôn Độc lập ngày 2/9/1945?', 'Chủ tịch Hồ Chí Minh đã đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, khai sinh nước Việt Nam Dân chủ Cộng hòa.', 'easy', true),
    (3, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'doc-lap-1945'), 'Nước Việt Nam Dân chủ Cộng hòa ra đời vào ngày nào?', 'Ngày 2/9/1945 là thời điểm Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa.', 'easy', true),
    (4, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'dien-bien-phu'), 'Chiến thắng Điện Biên Phủ diễn ra vào năm nào?', 'Chiến thắng Điện Biên Phủ diễn ra ngày 7/5/1954, kết thúc thắng lợi cuộc tiến công chiến lược kéo dài 56 ngày đêm.', 'easy', true),
    (5, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'dien-bien-phu'), 'Ai là Đại tướng chỉ huy chiến dịch Điện Biên Phủ?', 'Đại tướng Võ Nguyên Giáp là Tổng chỉ huy chiến dịch Điện Biên Phủ, gắn với chiến thắng lịch sử năm 1954.', 'easy', true),
    (6, (select id from public.eras where slug = 'thong-nhat'), (select id from public.events where slug = 'giai-phong-1975'), 'Ngày Giải phóng miền Nam, thống nhất đất nước là ngày nào?', 'Ngày 30/4/1975, Chiến dịch Hồ Chí Minh toàn thắng, kết thúc cuộc kháng chiến chống Mỹ, cứu nước.', 'easy', true),
    (7, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'tet-mau-than'), 'Tổng tiến công và nổi dậy Tết Mậu Thân diễn ra vào năm nào?', 'Tổng tiến công và nổi dậy Tết Mậu Thân nổ ra đầu năm 1968, tạo bước ngoặt lớn trong cuộc kháng chiến chống Mỹ.', 'easy', true),
    (8, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'hiep-dinh-paris'), 'Hiệp định Paris được ký vào năm nào?', 'Hiệp định Paris được ký ngày 27/1/1973, buộc Mỹ rút quân và tạo điều kiện thuận lợi cho cách mạng Việt Nam.', 'easy', true),
    (9, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'duong-truong-son'), 'Đoàn 559 mở đường Trường Sơn được thành lập năm nào?', 'Đoàn 559 được thành lập ngày 19/5/1959 để mở đường Trường Sơn, tuyến chi viện chiến lược Bắc - Nam.', 'easy', true),
    (10, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'hiep-dinh-geneva'), 'Hiệp định Giơnevơ về Đông Dương được ký tại thành phố nào?', 'Hiệp định Giơnevơ được ký tại Geneva, Thụy Sĩ, vào tháng 7/1954.', 'easy', true),
    (11, (select id from public.eras where slug = 'chong-phap'), null, 'Cuộc Tổng tuyển cử bầu Quốc hội đầu tiên của nước Việt Nam Dân chủ Cộng hòa diễn ra ngày nào?', 'Ngày 6/1/1946, nhân dân cả nước đi bầu Quốc hội khóa I, xây dựng nền dân chủ cộng hòa non trẻ.', 'easy', true),
    (12, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'khang-chien-1946'), 'Lời kêu gọi Toàn quốc kháng chiến được phát đi vào thời điểm nào?', 'Tối 19/12/1946, Chủ tịch Hồ Chí Minh ra Lời kêu gọi Toàn quốc kháng chiến, mở đầu cuộc kháng chiến chống Pháp trên phạm vi cả nước.', 'easy', true),
    (13, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'chien-dich-bien-gioi'), 'Chiến dịch Biên giới Thu - Đông diễn ra vào năm nào?', 'Chiến dịch Biên giới Thu - Đông 1950 là chiến dịch lớn đánh dấu bước phát triển mới của quân đội ta.', 'easy', true),
    (14, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'doc-lap-1945'), 'Tuyên ngôn Độc lập được đọc tại đâu?', 'Tuyên ngôn Độc lập được Chủ tịch Hồ Chí Minh đọc tại Quảng trường Ba Đình, Hà Nội.', 'easy', true),
    (15, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'hiep-dinh-geneva'), 'Thủ đô nào được giải phóng ngày 10/10/1954?', 'Ngày 10/10/1954, Hà Nội được giải phóng, đánh dấu bước chuyển quan trọng của miền Bắc sang thời kỳ hòa bình xây dựng.', 'easy', true),
    (16, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'duong-truong-son'), 'Mục đích chiến lược quan trọng của đường Trường Sơn là gì?', 'Đường Trường Sơn là tuyến chi viện chiến lược, bảo đảm vận chuyển lực lượng và vật chất từ miền Bắc vào miền Nam.', 'easy', true),
    (17, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'hiep-dinh-paris'), 'Theo Hiệp định Paris, lực lượng nào phải rút khỏi miền Nam Việt Nam?', 'Một nội dung quan trọng của Hiệp định Paris là Mỹ cam kết rút quân và chấm dứt can thiệp quân sự trực tiếp ở miền Nam Việt Nam.', 'easy', true),
    (18, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'hiep-dinh-geneva'), 'Sau Hiệp định Giơnevơ 1954, giới tuyến quân sự tạm thời ở Việt Nam nằm tại vĩ tuyến nào?', 'Hiệp định Giơnevơ quy định giới tuyến quân sự tạm thời ở Việt Nam tại vĩ tuyến 17.', 'easy', true),
    (19, (select id from public.eras where slug = 'thong-nhat'), (select id from public.events where slug = 'chien-dich-ho-chi-minh'), 'Chiến dịch Hồ Chí Minh toàn thắng diễn ra trong bao nhiêu ngày?', 'Chiến dịch Hồ Chí Minh diễn ra từ ngày 26/4 đến 30/4/1975, kết thúc sau 5 ngày.', 'easy', true),
    (20, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'tet-mau-than'), 'Một tác động lớn của cuộc Tổng tiến công và nổi dậy Tết Mậu Thân 1968 là gì?', 'Tết Mậu Thân 1968 tạo cú sốc lớn về chính trị và quân sự, buộc Mỹ phải xuống thang chiến tranh và đi vào đàm phán.', 'easy', true),
    (21, (select id from public.eras where slug = 'chong-phap'), null, 'Hiệp định Sơ bộ giữa Việt Nam và Pháp được ký vào ngày nào?', 'Hiệp định Sơ bộ ngày 6/3/1946 là một bước đi ngoại giao quan trọng để tranh thủ thời gian cho cách mạng Việt Nam.', 'medium', true),
    (22, (select id from public.eras where slug = 'chong-phap'), null, 'Tạm ước Việt - Pháp được ký ngày nào?', 'Tạm ước Việt - Pháp được ký ngày 14/9/1946 trong nỗ lực tiếp tục giữ hòa bình của Chính phủ Việt Nam.', 'medium', true),
    (23, (select id from public.eras where slug = 'chong-phap'), null, 'Đại hội đại biểu toàn quốc lần thứ II của Đảng diễn ra năm nào?', 'Đại hội II của Đảng họp đầu năm 1951, đánh dấu bước trưởng thành về tổ chức và đường lối lãnh đạo kháng chiến.', 'medium', true),
    (24, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'chien-dich-bien-gioi'), 'Mục tiêu nổi bật của Chiến dịch Biên giới 1950 là gì?', 'Chiến dịch Biên giới 1950 có ý nghĩa rất lớn trong việc khai thông biên giới, mở rộng căn cứ kháng chiến và tăng cường quan hệ quốc tế.', 'medium', true),
    (25, (select id from public.eras where slug = 'chong-phap'), null, 'Luật Cải cách ruộng đất được ban hành vào năm nào?', 'Luật Cải cách ruộng đất được ban hành cuối năm 1953 nhằm củng cố hậu phương và động viên nông dân trong kháng chiến.', 'medium', true),
    (26, (select id from public.eras where slug = 'chong-phap'), null, 'Chiến thắng Tây Bắc diễn ra vào năm nào?', 'Chiến thắng Tây Bắc năm 1952 góp phần mở rộng vùng giải phóng và chuẩn bị điều kiện cho các chiến dịch lớn tiếp theo.', 'medium', true),
    (27, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'dien-bien-phu'), 'Tướng De Castries bị bắt sống trong chiến dịch nào?', 'Ngày 7/5/1954, tướng De Castries bị bắt sống tại sở chỉ huy tập đoàn cứ điểm Điện Biên Phủ.', 'medium', true),
    (28, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'hiep-dinh-geneva'), 'Vấn đề Đông Dương được đưa ra bàn tại Hội nghị Giơnevơ từ ngày nào?', 'Hội nghị Giơnevơ khai mạc ngày 26/4/1954, nhưng từ ngày 8/5/1954 mới chính thức bàn về vấn đề Đông Dương.', 'medium', true),
    (29, (select id from public.eras where slug = 'thong-nhat'), (select id from public.events where slug = 'phuoc-long'), 'Tỉnh nào được giải phóng hoàn toàn đầu tiên trong Tổng tiến công mùa Xuân 1975, tạo ra bước thử chiến lược quan trọng?', 'Thắng lợi Phước Long đầu năm 1975 giúp ta đánh giá tương quan lực lượng và phản ứng của Mỹ trước khả năng giải phóng hoàn toàn miền Nam.', 'medium', true),
    (30, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'duong-truong-son'), 'Đoàn 559 được thành lập vào ngày nào?', 'Đoàn 559 được thành lập ngày 19/5/1959, mở đầu tuyến vận tải chiến lược Trường Sơn.', 'medium', true),
    (31, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'dien-bien-phu'), 'Kế hoạch quân sự nào của Pháp - Mỹ bị đánh bại trong chiến thắng Điện Biên Phủ?', 'Chiến thắng Điện Biên Phủ đã đập tan Kế hoạch Nava, làm phá sản nỗ lực quân sự lớn cuối cùng của Pháp - Mỹ ở Đông Dương.', 'hard', true),
    (32, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'dien-bien-phu'), 'Cứ điểm nào bị quân ta tiến công mở màn trong chiến dịch Điện Biên Phủ?', 'Đêm 13/3/1954, quân ta nổ súng mở màn chiến dịch Điện Biên Phủ bằng trận đánh vào Him Lam.', 'hard', true),
    (33, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'khang-chien-1946'), 'Hội nghị nào quyết định phát động Toàn quốc kháng chiến vào cuối năm 1946?', 'Ngày 18 và 19/12/1946, Hội nghị Vạn Phúc đã quyết định phát động Toàn quốc kháng chiến.', 'hard', true),
    (34, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'chien-dich-bien-gioi'), 'Sau Chiến dịch Biên giới Thu - Đông 1950, quân ta giành được ưu thế chiến lược nào?', 'Chiến dịch Biên giới 1950 giúp quân ta chuyển sang thế chủ động chiến lược trên chiến trường chính Bắc Bộ.', 'hard', true),
    (35, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'hiep-dinh-paris'), 'Hiệp định Paris được ký chính thức vào ngày nào?', 'Hiệp định Paris được ký ngày 27/1/1973, đánh dấu thắng lợi lớn trên mặt trận ngoại giao của nhân dân Việt Nam.', 'hard', true),
    (36, (select id from public.eras where slug = 'thong-nhat'), (select id from public.events where slug = 'phuoc-long'), 'Ý nghĩa chiến lược nổi bật của thắng lợi Phước Long đầu năm 1975 là gì?', 'Thắng lợi Phước Long cho thấy khả năng Mỹ khó quay lại can thiệp trực tiếp, tạo thêm cơ sở cho quyết tâm giải phóng hoàn toàn miền Nam.', 'hard', true),
    (37, (select id from public.eras where slug = 'chong-phap'), null, 'Trình tự thời gian nào dưới đây là đúng?', 'Trật tự phát triển của các chiến dịch lớn trong kháng chiến chống Pháp là Biên giới 1950, Tây Bắc 1952 và Điện Biên Phủ 1954.', 'hard', true),
    (38, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'hiep-dinh-geneva'), 'Con sông gắn với giới tuyến quân sự tạm thời sau Hiệp định Giơnevơ là sông nào?', 'Giới tuyến quân sự tạm thời sau Hiệp định Giơnevơ gắn với khu vực sông Bến Hải, gần vĩ tuyến 17.', 'hard', true),
    (39, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'tet-mau-than'), 'Trong Tết Mậu Thân 1968, quân và dân ta đã đồng loạt tiến công vào khoảng bao nhiêu đô thị, thị xã?', 'Tết Mậu Thân 1968 là cuộc tiến công đồng loạt vào hơn 100 đô thị, thị xã trên toàn miền Nam.', 'hard', true),
    (40, (select id from public.eras where slug = 'thong-nhat'), (select id from public.events where slug = 'chien-dich-ho-chi-minh'), 'Mục tiêu trực tiếp của Chiến dịch Hồ Chí Minh là gì?', 'Chiến dịch Hồ Chí Minh hướng tới mục tiêu trực tiếp là giải phóng Sài Gòn - Gia Định, kết thúc thắng lợi cuộc kháng chiến chống Mỹ.', 'hard', true),
    (41, (select id from public.eras where slug = 'chong-phap'), null, 'Thứ tự nào phản ánh đúng tiến trình từ giành chính quyền đến bước vào kháng chiến toàn quốc?', 'Tiến trình đúng là giành chính quyền trong Cách mạng Tháng Tám, tuyên bố độc lập, tổ chức tổng tuyển cử và sau đó bước vào cuộc kháng chiến toàn quốc.', 'hard', true),
    (42, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'dien-bien-phu'), 'Vì sao chiến thắng Điện Biên Phủ được coi là trận quyết chiến chiến lược?', 'Điện Biên Phủ là trận quyết chiến chiến lược vì nó đập tan nỗ lực quân sự chủ yếu của Pháp, tạo bước ngoặt quyết định trên cả chiến trường và bàn đàm phán.', 'hard', true),
    (43, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'hiep-dinh-paris'), 'Ý nghĩa nổi bật nhất của Hiệp định Paris 1973 đối với cách mạng Việt Nam là gì?', 'Hiệp định Paris 1973 là thắng lợi lớn trên mặt trận ngoại giao, buộc Mỹ rút quân và tạo điều kiện thuận lợi để cách mạng miền Nam tiến lên giải phóng hoàn toàn.', 'hard', true),
    (44, (select id from public.eras where slug = 'chong-my'), null, 'Sau năm 1954, nhiệm vụ cơ bản của miền Bắc xã hội chủ nghĩa là gì?', 'Sau 1954, miền Bắc bước vào thời kỳ xây dựng chủ nghĩa xã hội và trở thành hậu phương lớn cho cuộc đấu tranh giải phóng miền Nam.', 'hard', true),
    (45, (select id from public.eras where slug = 'chong-my'), (select id from public.events where slug = 'duong-truong-son'), 'Vì sao đường Trường Sơn được xem là tuyến chi viện chiến lược đặc biệt quan trọng?', 'Đường Trường Sơn giữ vai trò sống còn trong việc bảo đảm lực lượng, vũ khí và hậu cần cho chiến trường miền Nam.', 'hard', true),
    (46, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'hiep-dinh-geneva'), 'Sự kiện nào trực tiếp tạo thế mạnh cho phái đoàn Việt Nam tại Hội nghị Giơnevơ?', 'Thắng lợi Điện Biên Phủ tạo ra thế mạnh quân sự và chính trị trực tiếp cho phái đoàn Việt Nam tại Hội nghị Giơnevơ.', 'hard', true),
    (47, (select id from public.eras where slug = 'chong-phap'), (select id from public.events where slug = 'hiep-dinh-geneva'), 'Theo Hiệp định Giơnevơ, vĩ tuyến 17 có ý nghĩa như thế nào?', 'Hiệp định Giơnevơ chỉ quy định vĩ tuyến 17 là giới tuyến quân sự tạm thời, không phải biên giới chia cắt lâu dài đất nước.', 'hard', true),
    (48, (select id from public.eras where slug = 'thong-nhat'), (select id from public.events where slug = 'phuoc-long'), 'Thắng lợi nào mở ra khả năng giải phóng hoàn toàn miền Nam trong thời gian ngắn vào năm 1975?', 'Thắng lợi Phước Long là căn cứ thực tiễn quan trọng để Đảng nhận định thời cơ giải phóng hoàn toàn miền Nam đã chín muồi.', 'hard', true),
    (49, (select id from public.eras where slug = 'chong-phap'), null, 'Ý nghĩa quan trọng của ngày 10/10/1954 đối với miền Bắc là gì?', 'Ngày 10/10/1954, Hà Nội được giải phóng, thể hiện thắng lợi cụ thể của cuộc kháng chiến chống Pháp trên miền Bắc.', 'hard', true),
    (50, (select id from public.eras where slug = 'chong-phap'), null, 'Điểm chung của Cách mạng Tháng Tám 1945, Điện Biên Phủ 1954 và Đại thắng mùa Xuân 1975 là gì?', 'Ba mốc này đều là những thắng lợi có ý nghĩa quyết định, đưa cách mạng Việt Nam sang những bước phát triển mới về độc lập, chủ quyền và thống nhất đất nước.', 'hard', true)
